import{_ as a,H as e,f as r,i as o}from"./chunks/framework.Cvt1eIE0.js";const _=JSON.parse('{"title":"哲学","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/philosophy.md","filePath":"zh/guide/philosophy.md"}'),d={name:"zh/guide/philosophy.md"};function i(h,t,n,s,l,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="哲学" tabindex="-1">哲学 <a class="header-anchor" href="#哲学" aria-label="Permalink to &quot;哲学&quot;">​</a></h1><h2 id="目标驱动-不是指令驱动" tabindex="-1">目标驱动，不是指令驱动 <a class="header-anchor" href="#目标驱动-不是指令驱动" aria-label="Permalink to &quot;目标驱动，不是指令驱动&quot;">​</a></h2><p>告诉智能体要达到什么，完成长什么样。让它自己决定怎么做。</p><p>逐步食谱随着智能体变强会过时。但目标的声明保持相关 —— 它们编码了<strong>什么重要</strong>，而不是<strong>怎么做</strong>。</p><h2 id="只为有回报的纪律付出代价" tabindex="-1">只为有回报的纪律付出代价 <a class="header-anchor" href="#只为有回报的纪律付出代价" aria-label="Permalink to &quot;只为有回报的纪律付出代价&quot;">​</a></h2><p>分类决定了一切。修个拼写错误不需要规范。新系统需要。Praxis 按复杂度应用开销。</p><table tabindex="0"><thead><tr><th>任务</th><th>Praxis 成本</th></tr></thead><tbody><tr><td>修个拼写错误</td><td>~450 token（仅启动）</td></tr><tr><td>标准功能（design→ship）</td><td>~1,300 token</td></tr><tr><td>复杂任务（所有技能）</td><td>~2,900 token</td></tr></tbody></table><h2 id="技能是短的" tabindex="-1">技能是短的 <a class="header-anchor" href="#技能是短的" aria-label="Permalink to &quot;技能是短的&quot;">​</a></h2><p>如果一条规则需要 3,000 token 来表达，它可能不是规则 —— 它是手册。Praxis 技能平均 ~230 token。</p><p>短的技能意味着智能体完整阅读、可靠遵循，而且框架在 AI 能力演进时保持可维护。</p><h2 id="规范是事实-不是计划" tabindex="-1">规范是事实，不是计划 <a class="header-anchor" href="#规范是事实-不是计划" aria-label="Permalink to &quot;规范是事实，不是计划&quot;">​</a></h2><p>规范是决策列表：契约、不变量、失败模式、测试标准。没有叙述，没有理由，没有步骤。计划是分开的，它们是里程碑框架 —— 不是脚本。</p><p>智能体带来领域知识。Praxis 提供需要决策的结构，而不是怎样决策的指令。</p>',13)])])}const u=a(d,[["render",i]]);export{_ as __pageData,u as default};
